## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/brightFuturesLogic.ts`

```typescript
/**
 * Bright Futures Well-Child Care Clinical Compass™
 * Logic Engine — AAP Preventive Pediatric Health Care 2025 (Bright Futures 4th Edition)
 *
 * References:
 * 1. Hagan JF, Shaw JS, Duncan PM (eds). Bright Futures: Guidelines for Health
 *    Supervision of Infants, Children, and Adolescents, 4th Edition. AAP. 2017 (2025 update).
 * 2. AAP Bright Futures Periodicity Schedule 2025.
 * 3. USPSTF Pediatric Preventive Services 2025.
 * 4. AAP Developmental Surveillance and Screening Policy. Pediatrics. 2020 (reaffirmed 2025).
 */

export type WellChildVisitAge =
  | "3_5_days"
  | "1_month"
  | "2_months"
  | "4_months"
  | "6_months"
  | "9_months"
  | "12_months"
  | "15_months"
  | "18_months"
  | "24_months"
  | "30_months"
  | "3_years"
  | "4_years"
  | "5_years"
  | "6_years"
  | "7_years"
  | "8_years"
  | "9_years"
  | "10_years"
  | "11_years"
  | "12_years"
  | "13_years"
  | "14_years"
  | "15_years"
  | "16_years"
  | "17_years"
  | "18_years"
  | "19_21_years";

export interface BrightFuturesInput {
  visitAge: WellChildVisitAge;
  sex: "male" | "female" | "other";
  bmiPercentile: number | null; // null if not yet measurable (< 2 years)
  weightForLengthPercentile: number | null; // for < 2 years
  developmentalConcerns: boolean;
  m_chatScore: number | null; // M-CHAT-R/F score (16–30 months)
  phq2Score: number | null; // PHQ-2 (adolescents ≥12 years)
  phq9Score: number | null; // PHQ-9 if PHQ-2 positive
  asqScore: "normal" | "monitor" | "refer" | null; // Ages & Stages Questionnaire
  hasVisionConcerns: boolean;
  hasHearingConcerns: boolean;
  leadRiskFactors: boolean;
  ironDeficiencyRisk: boolean;
  tbExposureRisk: boolean;
  dyslipidemiRisk: boolean; // family history or obesity
  sexuallyActive: boolean; // adolescents
  substanceUseScreenPositive: boolean; // CRAFFT or AUDIT-C
  tobaccoExposure: boolean; // secondhand smoke
  familySocialRisks: boolean; // food insecurity, housing instability, domestic violence
  isAdolescent: boolean;
  hasChronicCondition: boolean;
}

export interface ScreeningResult {
  screening: string;
  method: string;
  result: string;
  action: string;
  frequency: string;
}

export interface BrightFuturesRecommendation {
  primaryRecommendation: string;
  screeningsRequired: ScreeningResult[];
  anticipatoryGuidance: string[];
  immunizationsNote: string;
  developmentalAssessment: string;
  urgentFlags: string[];
  referrals: string[];
  nextVisit: string;
  evidenceLevel: "A" | "B" | "C";
  rationale: string;
  references: Array<{ citation: string; url: string }>;
}

export function assessBrightFutures(
  input: BrightFuturesInput
): BrightFuturesRecommendation {
  const screenings: ScreeningResult[] = [];
  const guidance: string[] = [];
  const urgentFlags: string[] = [];
  const referrals: string[] = [];

  const ageYears = parseVisitAgeToYears(input.visitAge);

  // ─── Universal screenings at every visit ────────────────────────────────
  screenings.push(
    { screening: "Height/Weight/BMI", method: "Measured and plotted on CDC growth chart", result: input.bmiPercentile !== null ? `BMI %ile: ${input.bmiPercentile}` : input.weightForLengthPercentile !== null ? `Wt/Length %ile: ${input.weightForLengthPercentile}` : "Not yet applicable", action: "Plot on growth chart; assess trend", frequency: "Every visit" },
    { screening: "Blood Pressure", method: "Auscultatory or oscillometric", result: "Measure from age 3 years; earlier if risk factors", action: "Compare to age/sex/height normative tables (AAP 2017 CPG)", frequency: "Annually ≥3 years" }
  );

  // ─── Obesity / BMI screening ─────────────────────────────────────────────
  if (input.bmiPercentile !== null) {
    if (input.bmiPercentile >= 95) {
      urgentFlags.push(`BMI ≥95th percentile: OBESITY — initiate AAP 2023 intensive health behavior and lifestyle treatment (IHBLT). Consider pharmacotherapy (≥12 years) or bariatric surgery (≥13 years) per AAP CPG 2023.`);
      screenings.push({ screening: "Obesity workup", method: "Fasting lipids, HbA1c, ALT/AST, TSH", result: `BMI ${input.bmiPercentile}th percentile`, action: "Initiate IHBLT. Refer to obesity medicine or pediatric weight management program", frequency: "At diagnosis and follow-up" });
    } else if (input.bmiPercentile >= 85) {
      urgentFlags.push(`BMI 85–94th percentile: OVERWEIGHT — counsel on healthy lifestyle. Assess for comorbidities. Refer to weight management if lifestyle counseling insufficient.`);
    }
  }

  // ─── Developmental surveillance & screening ──────────────────────────────
  let devAssessment = "Developmental surveillance at every visit using structured observation and parent-reported concerns.";

  if (ageYears <= 3) {
    screenings.push({ screening: "Developmental Screening (ASQ-3)", method: "Ages & Stages Questionnaire, 3rd edition", result: input.asqScore ? `ASQ: ${input.asqScore}` : "Administer at 9, 18, 30 months", action: input.asqScore === "refer" ? "REFER to early intervention (EI) — do not delay" : input.asqScore === "monitor" ? "Rescreen in 1–2 months" : "Continue surveillance", frequency: "9, 18, 30 months (AAP 2020)" });
    if (input.asqScore === "refer") {
      urgentFlags.push("DEVELOPMENTAL SCREEN POSITIVE: Refer to early intervention (Part C, IDEA) immediately. Do not wait for diagnosis to refer.");
      referrals.push("Early Intervention (EI) referral — Part C IDEA. Simultaneous referral to developmental pediatrician or neurodevelopmental specialist.");
    }
  }

  // ─── Autism screening (M-CHAT-R/F) ───────────────────────────────────────
  if ((input.visitAge === "18_months" || input.visitAge === "24_months") && input.m_chatScore !== null) {
    const mChatRisk = input.m_chatScore >= 3 ? "high" : input.m_chatScore >= 2 ? "medium" : "low";
    screenings.push({ screening: "Autism Screening (M-CHAT-R/F)", method: "Modified Checklist for Autism in Toddlers, Revised with Follow-Up", result: `Score: ${input.m_chatScore} (${mChatRisk} risk)`, action: mChatRisk === "high" ? "Refer to autism specialist + EI immediately" : mChatRisk === "medium" ? "Administer follow-up interview; refer if still positive" : "Continue surveillance", frequency: "18 and 24 months" });
    if (mChatRisk === "high") {
      urgentFlags.push(`M-CHAT-R/F HIGH RISK (score ${input.m_chatScore}): Refer for comprehensive autism evaluation and early intervention immediately. Do not wait for diagnosis.`);
      referrals.push("Autism evaluation: developmental pediatrics, child psychiatry, or neurology. Simultaneous EI referral for ABA/speech/OT.");
    }
  }

  // ─── Vision screening ────────────────────────────────────────────────────
  if (ageYears >= 3) {
    screenings.push({ screening: "Vision Screening", method: "Instrument-based (photoscreening) preferred ≥1 year; visual acuity chart ≥3 years", result: input.hasVisionConcerns ? "Concerns reported" : "No concerns", action: input.hasVisionConcerns ? "Refer to pediatric ophthalmology" : "Continue annual screening", frequency: "Annually ≥3 years; instrument-based at 12 and 24 months" });
    if (input.hasVisionConcerns) referrals.push("Pediatric ophthalmology referral for vision concerns.");
  }

  // ─── Hearing screening ───────────────────────────────────────────────────
  if (input.visitAge === "3_5_days") {
    screenings.push({ screening: "Newborn Hearing Screening (UNHS)", method: "OAE or ABR before hospital discharge", result: "Universal newborn hearing screening — mandatory in all 50 states", action: "Refer to audiologist if fail. Diagnosis by 3 months, intervention by 6 months (EHDI 1-3-6 goals)", frequency: "Birth" });
  } else if (ageYears >= 4 && ageYears <= 10) {
    screenings.push({ screening: "Hearing Screening", method: "Pure-tone audiometry", result: input.hasHearingConcerns ? "Concerns present" : "No concerns", action: input.hasHearingConcerns ? "Refer to audiology" : "Continue periodic screening", frequency: "Ages 4, 5, 6, 8, 10 years" });
  }

  // ─── Lead screening ──────────────────────────────────────────────────────
  if (ageYears >= 1 && ageYears <= 2) {
    screenings.push({ screening: "Lead Screening", method: "Blood lead level (BLL)", result: input.leadRiskFactors ? "Risk factors present" : "Universal at 12 and 24 months in high-risk communities", action: "BLL ≥3.5 μg/dL: case management, environmental investigation. BLL ≥45 μg/dL: chelation therapy", frequency: "12 and 24 months; risk-based thereafter" });
    if (input.leadRiskFactors) urgentFlags.push("LEAD RISK FACTORS: Obtain blood lead level. BLL ≥3.5 μg/dL requires case management and environmental investigation.");
  }

  // ─── Iron deficiency screening ───────────────────────────────────────────
  if (ageYears >= 1 && ageYears <= 3 && input.ironDeficiencyRisk) {
    screenings.push({ screening: "Iron Deficiency Screening", method: "Hemoglobin or hematocrit", result: "Risk factors present", action: "Hgb <11 g/dL: trial of iron supplementation. No response → further evaluation", frequency: "12 months universal; risk-based 1–5 years" });
  }

  // ─── TB screening ────────────────────────────────────────────────────────
  if (input.tbExposureRisk) {
    screenings.push({ screening: "TB Screening", method: "TST or IGRA (IGRA preferred ≥2 years)", result: "Risk factors present", action: "Positive screen: chest X-ray, infectious disease referral", frequency: "Risk-based" });
    referrals.push("Infectious disease referral for TB exposure risk assessment.");
  }

  // ─── Dyslipidemia screening ──────────────────────────────────────────────
  if ((ageYears >= 9 && ageYears <= 11) || (ageYears >= 17 && ageYears <= 21) || input.dyslipidemiRisk) {
    screenings.push({ screening: "Dyslipidemia Screening (Fasting Lipid Panel)", method: "Fasting lipid panel", result: input.dyslipidemiRisk ? "Risk factors present (family history or obesity)" : "Universal at 9–11 and 17–21 years", action: "LDL ≥130 mg/dL: dietary counseling. LDL ≥190 mg/dL: consider statin (≥10 years)", frequency: "Universal at 9–11 years and 17–21 years; risk-based at other ages" });
  }

  // ─── Depression screening ────────────────────────────────────────────────
  if (ageYears >= 12) {
    const phq2Result = input.phq2Score !== null ? `PHQ-2 score: ${input.phq2Score}` : "Administer PHQ-2";
    const phq2Action = input.phq2Score !== null && input.phq2Score >= 2
      ? "PHQ-2 POSITIVE: Administer PHQ-9. Score ≥10: refer to mental health. Score ≥20 or SI: urgent psychiatric evaluation"
      : "PHQ-2 negative: continue annual screening";
    screenings.push({ screening: "Depression Screening (PHQ-2/PHQ-9)", method: "Patient Health Questionnaire-2 (PHQ-2), then PHQ-9 if positive", result: phq2Result, action: phq2Action, frequency: "Annually ≥12 years (AAP/USPSTF)" });
    if (input.phq2Score !== null && input.phq2Score >= 2) {
      urgentFlags.push(`PHQ-2 POSITIVE (score ${input.phq2Score}): Administer PHQ-9. Assess for suicidal ideation. Refer to mental health services.`);
      if (input.phq9Score !== null && input.phq9Score >= 20) {
        urgentFlags.push(`PHQ-9 SEVERE (score ${input.phq9Score}): URGENT psychiatric evaluation. Assess for active suicidal ideation and safety plan.`);
        referrals.push("URGENT: Psychiatric evaluation for severe depression (PHQ-9 ≥20).");
      } else if (input.phq9Score !== null && input.phq9Score >= 10) {
        referrals.push("Mental health referral for moderate-severe depression (PHQ-9 ≥10).");
      }
    }
  }

  // ─── Substance use screening ─────────────────────────────────────────────
  if (ageYears >= 11) {
    screenings.push({ screening: "Substance Use Screening (CRAFFT)", method: "CRAFFT 2.1 (Car, Relax, Alone, Forget, Friends, Trouble)", result: input.substanceUseScreenPositive ? "CRAFFT positive" : "CRAFFT negative", action: input.substanceUseScreenPositive ? "Brief intervention (BI). Refer to substance use treatment if moderate-severe use" : "Anticipatory guidance on substance avoidance", frequency: "Annually ≥11 years" });
    if (input.substanceUseScreenPositive) {
      urgentFlags.push("SUBSTANCE USE SCREEN POSITIVE: Conduct brief intervention (BI). Refer to adolescent substance use treatment if CRAFFT ≥2.");
      referrals.push("Adolescent substance use treatment referral (CRAFFT ≥2).");
    }
  }

  // ─── STI/sexual health screening ─────────────────────────────────────────
  if (input.sexuallyActive && ageYears >= 13) {
    screenings.push(
      { screening: "Chlamydia/Gonorrhea Screening", method: "NAAT (urine or vaginal swab)", result: "Sexually active", action: "Annual screening for all sexually active adolescents. Treat per CDC STI guidelines 2021", frequency: "Annually if sexually active" },
      { screening: "HIV Screening", method: "4th-generation HIV Ag/Ab combo test", result: "Sexually active", action: "Opt-out HIV screening. Confirm positive with Western blot or NAAT", frequency: "At least once; annually if high risk" }
    );
    if (input.sex === "female") {
      screenings.push({ screening: "Pregnancy Prevention Counseling", method: "Counseling + contraception discussion", result: "Sexually active female", action: "Discuss contraceptive options including LARC. Offer HPV vaccination if not complete", frequency: "Every visit if sexually active" });
    }
  }

  // ─── Anticipatory guidance ────────────────────────────────────────────────
  if (ageYears < 1) {
    guidance.push(
      "Safe sleep: Back to sleep, firm flat surface, no soft bedding, no bed-sharing (AAP SIDS prevention 2022).",
      "Breastfeeding: Exclusive breastfeeding for 6 months, continue with complementary foods to 12 months or beyond.",
      "Vitamin D supplementation: 400 IU/day starting in first few days of life for breastfed infants.",
      "Car seat: Rear-facing until maximum weight/height limit of seat.",
      "Tummy time: Supervised tummy time when awake to prevent positional plagiocephaly."
    );
  } else if (ageYears < 2) {
    guidance.push(
      "No screen time except video chatting for children <18–24 months (AAP 2016 media policy).",
      "Introduce allergenic foods (peanuts, eggs, tree nuts) early — LEAP trial evidence supports early introduction.",
      "Iron-rich foods: Introduce iron-fortified cereals and pureed meats at 6 months.",
      "Dental care: First dental visit by age 1. Fluoride varnish application at well-child visits.",
      "Water fluoridation: If community water not fluoridated, prescribe fluoride drops."
    );
  } else if (ageYears < 6) {
    guidance.push(
      "Screen time: Limit to 1 hour/day of high-quality programming for ages 2–5 (AAP 2016).",
      "Reading aloud: Daily reading promotes language development and school readiness.",
      "Physical activity: 3 hours/day of active play for preschoolers.",
      "Dental hygiene: Brush twice daily with fluoride toothpaste (pea-sized amount ≥3 years).",
      "Helmet use: Bicycle helmets required for all riding activities."
    );
  } else if (ageYears < 12) {
    guidance.push(
      "Screen time: Consistent limits; avoid screens during meals and 1 hour before bedtime.",
      "Physical activity: 60 minutes of moderate-vigorous activity daily (MVPA).",
      "Sleep: 9–12 hours/night for ages 6–12 years.",
      "Bullying prevention: Discuss cyberbullying, peer relationships, and school safety.",
      "Sun protection: SPF ≥30 sunscreen, protective clothing, limit peak sun exposure."
    );
  } else {
    guidance.push(
      "Sleep: 8–10 hours/night for adolescents. Discuss sleep hygiene and screen use at bedtime.",
      "Physical activity: 60 minutes of MVPA daily. Limit sedentary screen time.",
      "Driving safety: Graduated driver licensing laws. No phone use while driving.",
      "Substance use prevention: Discuss risks of alcohol, marijuana, vaping, and opioids.",
      "Mental health: Normalize help-seeking. Provide crisis resources (988 Suicide & Crisis Lifeline).",
      "Social media: Discuss digital footprint, online safety, and mental health effects of social media."
    );
  }

  if (input.tobaccoExposure) {
    guidance.push("Secondhand smoke exposure: Counsel family on smoking cessation. Refer to quitline (1-800-QUIT-NOW). Tobacco smoke increases risk of SIDS, asthma, otitis media, and respiratory infections.");
    referrals.push("Smoking cessation referral for household members (1-800-QUIT-NOW or AAP Tobacco Cessation resources).");
  }

  if (input.familySocialRisks) {
    guidance.push("Social determinants of health (SDOH): Screen for food insecurity (Hunger Vital Sign), housing instability, and domestic violence. Connect to community resources (WIC, SNAP, housing assistance).");
    screenings.push({ screening: "Social Determinants of Health (SDOH)", method: "Hunger Vital Sign, PRAPARE, or WE CARE tool", result: "Risk factors identified", action: "Connect to WIC, SNAP, housing assistance, legal aid, domestic violence resources", frequency: "Every visit" });
  }

  // ─── Immunizations note ───────────────────────────────────────────────────
  const immunizationsNote = `Review and update immunizations per AAP 2026 Immunization Schedule at this ${input.visitAge.replace(/_/g, " ")} visit. Administer all due vaccines. Provide VIS for each vaccine administered.`;

  // ─── Next visit ───────────────────────────────────────────────────────────
  const nextVisitMap: Record<WellChildVisitAge, string> = {
    "3_5_days": "Return at 1 month",
    "1_month": "Return at 2 months",
    "2_months": "Return at 4 months",
    "4_months": "Return at 6 months",
    "6_months": "Return at 9 months",
    "9_months": "Return at 12 months",
    "12_months": "Return at 15 months",
    "15_months": "Return at 18 months",
    "18_months": "Return at 24 months",
    "24_months": "Return at 30 months",
    "30_months": "Return at 3 years",
    "3_years": "Return at 4 years",
    "4_years": "Return at 5 years",
    "5_years": "Return at 6 years",
    "6_years": "Return at 7 years",
    "7_years": "Return at 8 years",
    "8_years": "Return at 9 years",
    "9_years": "Return at 10 years",
    "10_years": "Return at 11 years",
    "11_years": "Return at 12 years",
    "12_years": "Return at 13 years",
    "13_years": "Return at 14 years",
    "14_years": "Return at 15 years",
    "15_years": "Return at 16 years",
    "16_years": "Return at 17 years",
    "17_years": "Return at 18 years",
    "18_years": "Return at 19–21 years",
    "19_21_years": "Transition to adult care. Provide warm handoff to adult primary care provider.",
  };

  const primaryRec = urgentFlags.length > 0
    ? urgentFlags[0]
    : `WELL-CHILD VISIT — ${input.visitAge.replace(/_/g, " ")}. ${screenings.length} screening(s) indicated. ${referrals.length > 0 ? `${referrals.length} referral(s) needed.` : "No urgent referrals."} Evidence Level A (Bright Futures 2025).`;

  return {
    primaryRecommendation: primaryRec,
    screeningsRequired: screenings,
    anticipatoryGuidance: guidance,
    immunizationsNote,
    developmentalAssessment: devAssessment,
    urgentFlags,
    referrals,
    nextVisit: nextVisitMap[input.visitAge] ?? "Follow Bright Futures periodicity schedule",
    evidenceLevel: "A",
    rationale: `Visit age: ${input.visitAge}. BMI %ile: ${input.bmiPercentile ?? "N/A"}. Developmental concerns: ${input.developmentalConcerns}. Recommendations per AAP Bright Futures 4th Edition (2025 update) and USPSTF 2025 pediatric preventive services.`,
    references: [
      { citation: "Hagan JF, Shaw JS, Duncan PM (eds). Bright Futures: Guidelines for Health Supervision of Infants, Children, and Adolescents, 4th Edition. AAP. 2017 (2025 update).", url: "https://brightfutures.aap.org" },
      { citation: "AAP Bright Futures Periodicity Schedule 2025. American Academy of Pediatrics.", url: "https://www.aap.org/en/practice-management/bright-futures/bright-futures-periodicity-schedule/" },
      { citation: "USPSTF. Screening for Depression and Suicide Risk in Children and Adolescents. JAMA. 2022;328(15):1534–1542.", url: "https://jamanetwork.com/journals/jama/fullarticle/2797177" },
      { citation: "AAP Council on Community Pediatrics. Poverty and Child Health in the United States. Pediatrics. 2016;137(4):e20160339.", url: "https://publications.aap.org/pediatrics/article/137/4/e20160339" },
    ],
  };
}

function parseVisitAgeToYears(age: WellChildVisitAge): number {
  const map: Record<WellChildVisitAge, number> = {
    "3_5_days": 0, "1_month": 0.08, "2_months": 0.17, "4_months": 0.33,
    "6_months": 0.5, "9_months": 0.75, "12_months": 1, "15_months": 1.25,
    "18_months": 1.5, "24_months": 2, "30_months": 2.5, "3_years": 3,
    "4_years": 4, "5_years": 5, "6_years": 6, "7_years": 7, "8_years": 8,
    "9_years": 9, "10_years": 10, "11_years": 11, "12_years": 12,
    "13_years": 13, "14_years": 14, "15_years": 15, "16_years": 16,
    "17_years": 17, "18_years": 18, "19_21_years": 19,
  };
  return map[age] ?? 0;
}
